php_code="<?php\ndeclare(strict_types=1);\nini_set('display_errors','0');\nrequire '/srv/celikom/app/staging-20261122/bootstrap.php';\n$config=require '/srv/celikom/app/staging-20261122/config/app.php';\n$pdo=Celikom\\Database\\Connection::open($config);\nfunction checkFlow(bool $ok,string $code):void {if(!$ok)throw new RuntimeException('flow_'.$code);}\nfunction uuidFlow():string {$h=bin2hex(random_bytes(16));return substr($h,0,8).'-'.substr($h,8,4).'-4'.substr($h,13,3).'-a'.substr($h,17,3).'-'.substr($h,20);}\nfunction requestFlow(string $method,string $path,?array $fields,string $token='',array $extra=[]):array {\n $ch=curl_init('https://api.celikom.com'.$path);$headers=['Origin: chrome-extension://'.str_repeat('a',32),'Expect:'];\n if($token!=='')$headers[]='Authorization: Bearer '.$token;\n foreach($extra as $header)$headers[]=$header;\n $responseHeaders=[];\n curl_setopt_array($ch,[CURLOPT_CUSTOMREQUEST=>$method,CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>false,\n  CURLOPT_PROXY=>'',CURLOPT_RESOLVE=>['api.celikom.com:443:127.0.0.1'],CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,\n  CURLOPT_CONNECTTIMEOUT=>5,CURLOPT_TIMEOUT=>35,CURLOPT_HTTPHEADER=>$headers,\n  CURLOPT_HEADERFUNCTION=>static function($ch,string $line)use(&$responseHeaders):int{$p=explode(':',$line,2);if(count($p)===2)$responseHeaders[strtolower(trim($p[0]))]=trim($p[1]);return strlen($line);}]);\n if($fields!==null)curl_setopt($ch,CURLOPT_POSTFIELDS,$fields);\n $raw=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);$errno=curl_errno($ch);curl_close($ch);\n checkFlow($raw!==false&&$errno===0,'http_transport');\n $body=json_decode((string)$raw,true);\n return ['status'=>$status,'body'=>is_array($body)?$body:[],'headers'=>$responseHeaders];\n}\n$tag=bin2hex(random_bytes(8));$email='contribution-qa-'.$tag.'@example.invalid';\n$password=bin2hex(random_bytes(24));$installation=uuidFlow();$attempt=uuidFlow();\n$track='7999'.(string)random_int(100000000000,999999999999);$uid=null;$assetId=null;$key=null;$rawPath=null;\n$ownerHash=null;$counts=['upload'=>0,'track_request'=>0];$success=false;\ntry {\n checkFlow(extension_loaded('curl'),'curl_required');\n checkFlow(($config['user_uploads_enabled']??false)===true,'public_contributions_disabled');\n foreach(['tracks','track_requests'] as $table){$s=$pdo->prepare(\"SELECT COUNT(*) FROM $table WHERE service='yandex' AND service_track_id=?\");$s->execute([$track]);checkFlow((int)$s->fetchColumn()===0,'reserved_track_collision');}\n $rawPath=tempnam(sys_get_temp_dir(),'celikom-contrib-qa-');checkFlow(is_string($rawPath),'fixture_temp');\n chmod($rawPath,0600);$frame=file_get_contents($argv[1]);checkFlow(is_string($frame)&&strlen($frame)>1024,'fixture_missing');\n file_put_contents($rawPath,str_repeat($frame,180));\n checkFlow(filesize($rawPath)>7000000&&filesize($rawPath)<10000000,'fixture_size');\n $prepared=(new Celikom\\Application\\Mp3Normalizer())->prepare($rawPath);\n try {$duration=$prepared['duration_ms'];$sha=hash_file('sha256',$prepared['path']);}\n finally{unlink($prepared['path']);}\n $key='audio/'.substr($sha,0,2).'/'.$sha.'.mp3';\n $s=$pdo->prepare('SELECT COUNT(*) FROM audio_assets WHERE sha256=?');$s->execute([$sha]);\n checkFlow((int)$s->fetchColumn()===0&&!is_file($config['storage_path'].'/'.$key),'fixture_asset_collision');\n $s=$pdo->prepare('INSERT INTO users(email,password_hash) VALUES(?,?)');\n $s->execute([$email,password_hash($password,PASSWORD_BCRYPT,['cost'=>12])]);$uid=(int)$pdo->lastInsertId();\n $pdo->prepare('INSERT INTO user_email_security(user_id,verified_at) VALUES(?,UTC_TIMESTAMP(6))')->execute([$uid]);\n $auth=new Celikom\\Auth\\AuthService($pdo,$config);\n $session=$auth->login(['email'=>$email,'password'=>$password,'installation_id'=>$installation],'127.0.0.1');\n checkFlow(is_string($session['access_token']??null),'qa_session');$token=$session['access_token'];\n $auth->activate($token);\n $ownerHash=hash_hmac('sha256','contribution.user.'.$uid,$config['analytics_privacy_key']);\n $r=requestFlow('OPTIONS','/api/v1/uploads',null,'',['Access-Control-Request-Method: POST','Access-Control-Request-Headers: authorization,x-celikom-upload-attempt']);\n checkFlow($r['status']===204&&($r['headers']['access-control-allow-origin']??'')==='chrome-extension://'.str_repeat('a',32),'extension_cors');\n echo \"CONTRIBUTION_EXTENSION_CORS_PASS\\n\";\n $r=requestFlow('POST','/api/v1/track-requests',['service'=>'yandex','track_id'=>$track]);\n checkFlow($r['status']===401,'anonymous_write_rejected');\n $statusPath='/api/v1/tracks/upload-status?service=yandex&track_id='.$track;\n $r=requestFlow('GET',$statusPath,null,$token);checkFlow($r['status']===200&&($r['body']['status']??'')==='none','empty_track_presence');\n $proposal=['service'=>'yandex','track_id'=>$track,'artist'=>'CELIKOM synthetic QA','title'=>'Temporary contribution check '.$tag];\n $r=requestFlow('POST','/api/v1/track-requests',$proposal,$token);$counts['track_request']++;\n checkFlow($r['status']===202&&($r['body']['status']??'')==='pending','proposal_202');$requestId=$r['body']['request_id'];\n $r=requestFlow('POST','/api/v1/track-requests',$proposal,$token);$counts['track_request']++;\n checkFlow($r['status']===202&&($r['body']['request_id']??null)===$requestId,'proposal_retry_idempotent');\n $s=$pdo->prepare(\"SELECT COUNT(*) FROM track_requests WHERE service='yandex' AND service_track_id=? AND uploader_hash=? AND status='pending'\");$s->execute([$track,$ownerHash]);checkFlow((int)$s->fetchColumn()===1,'proposal_queue');\n echo \"CONTRIBUTION_PROPOSE_PENDING_AND_DUPLICATE_PASS\\n\";\n $fields=$proposal+['duration_ms'=>(string)$duration,'album'=>'','declaration'=>'1','request_id'=>$attempt];\n $fields['file']=new CURLFile($rawPath,'audio/mpeg','synthetic-private-check.mp3');\n $r=requestFlow('POST','/api/v1/uploads',$fields,$token,['X-Celikom-Upload-Attempt: '.$attempt]);$counts['upload']++;\n checkFlow($r['status']===202&&($r['body']['status']??'')==='pending','multipart_202_http_'.$r['status']);$replacementId=$r['body']['replacement_id'];\n $r=requestFlow('POST','/api/v1/uploads',$fields,$token,['X-Celikom-Upload-Attempt: '.$attempt]);$counts['upload']++;\n checkFlow($r['status']===202&&($r['body']['replacement_id']??null)===$replacementId&&($r['body']['duplicate']??false)===true,'multipart_retry_idempotent');\n $s=$pdo->prepare('SELECT r.status,r.is_active,r.uploaded_by_user_id,r.audio_asset_id FROM track_replacements r JOIN tracks t ON t.id=r.track_id WHERE t.service=? AND t.service_track_id=?');$s->execute(['yandex',$track]);$rows=$s->fetchAll(PDO::FETCH_ASSOC);\n checkFlow(count($rows)===1&&$rows[0]['status']==='pending'&&(int)$rows[0]['is_active']===0&&(int)$rows[0]['uploaded_by_user_id']===$uid,'upload_queue_and_ownership');$assetId=(int)$rows[0]['audio_asset_id'];\n echo 'CONTRIBUTION_MULTIPART_'.filesize($rawPath).\"_BYTES_PENDING_AND_RETRY_PASS\\n\";\n $r=requestFlow('GET',$statusPath,null,$token);checkFlow($r['status']===200&&($r['body']['status']??'')==='pending','pending_presence');\n $r=requestFlow('POST','/api/v1/track-requests',$proposal,$token);$counts['track_request']++;\n checkFlow($r['status']===409&&($r['body']['error']??'')==='track_pending','proposal_after_upload_blocked');\n $s=$pdo->prepare('SELECT '.Celikom\\Application\\TrackRequestProgress::sql().\" AS progress FROM track_requests r WHERE r.service='yandex' AND r.service_track_id=? AND r.uploader_hash=?\");$s->execute([$track,$ownerHash]);checkFlow($s->fetchColumn()==='uploaded','proposal_linked_queue_progress');\n echo \"CONTRIBUTION_PROPOSAL_UPLOAD_LINKED_PROGRESS_PASS\\n\";\n $r=requestFlow('GET','/api/v1/resolve?service=yandex&track_id='.$track,null,$token);\n checkFlow(($r['status']===404)||($r['status']===200&&($r['body']['found']??null)===false),'pending_not_public');\n $r=requestFlow('GET','/api/v1/audio/'.$replacementId,null);checkFlow($r['status']===404,'pending_not_streamable');\n echo \"CONTRIBUTION_PENDING_NOT_PUBLIC_OR_STREAMABLE_PASS\\n\";\n $success=true;\n} catch(Throwable $e) {\n $m=$e->getMessage();echo 'CONTRIBUTION_FLOW_FAILED '.(preg_match('/^flow_[a-z0-9_]+$/D',$m)?$m:get_class($e)).\"\\n\";\n} finally {\n if($pdo->inTransaction())$pdo->rollBack();\n if($uid!==null){\n  $pdo->beginTransaction();\n  try{\n   $s=$pdo->prepare('SELECT id FROM users WHERE id=? AND email=? FOR UPDATE');$s->execute([$uid,$email]);checkFlow((int)$s->fetchColumn()===$uid,'cleanup_owner');\n   $s=$pdo->prepare(\"SELECT r.id,r.audio_asset_id,r.status,r.is_active FROM track_replacements r JOIN tracks t ON t.id=r.track_id WHERE t.service='yandex' AND t.service_track_id=? AND r.uploaded_by_user_id=? FOR UPDATE\");$s->execute([$track,$uid]);$owned=$s->fetchAll(PDO::FETCH_ASSOC);\n   foreach($owned as $row){checkFlow($row['status']==='pending'&&(int)$row['is_active']===0,'cleanup_only_pending');$assetId=(int)$row['audio_asset_id'];$pdo->prepare('DELETE FROM upload_submissions WHERE replacement_id=? AND uploader_hash=?')->execute([$row['id'],$ownerHash]);$pdo->prepare('DELETE FROM track_replacements WHERE id=? AND uploaded_by_user_id=?')->execute([$row['id'],$uid]);}\n   if($assetId!==null){$s=$pdo->prepare('SELECT COUNT(*) FROM track_replacements WHERE audio_asset_id=?');$s->execute([$assetId]);checkFlow((int)$s->fetchColumn()===0,'cleanup_asset_unshared');$pdo->prepare('DELETE FROM audio_fingerprint_jobs WHERE audio_asset_id=?')->execute([$assetId]);$pdo->prepare('DELETE FROM audio_assets WHERE id=? AND storage_key=?')->execute([$assetId,$key]);}\n   $pdo->prepare(\"DELETE FROM track_requests WHERE service='yandex' AND service_track_id=? AND uploader_hash=? AND status='pending'\")->execute([$track,$ownerHash]);\n   $pdo->prepare(\"DELETE FROM tracks WHERE service='yandex' AND service_track_id=? AND artist='CELIKOM synthetic QA'\")->execute([$track]);\n   foreach(['account_trials','entitlement_ledger','user_auth_events','user_sessions','user_devices','user_email_security'] as $table)$pdo->prepare(\"DELETE FROM $table WHERE user_id=?\")->execute([$uid]);\n   $pdo->prepare('DELETE FROM users WHERE id=? AND email=?')->execute([$uid,$email]);\n   foreach([$ownerHash,hash_hmac('sha256','contribution.device.'.$installation,$config['analytics_privacy_key'])] as $h)if(is_string($h))$pdo->prepare('DELETE FROM upload_rate_buckets WHERE identity_hash=?')->execute([$h]);\n   foreach($counts as $op=>$n)if($n>0){$h=hash_hmac('sha256','contribution.ip.127.0.0.1',$config['analytics_privacy_key']);$pdo->prepare('UPDATE upload_rate_buckets SET attempts=GREATEST(0,attempts-?) WHERE identity_hash=? AND window_start=? AND operation=?')->execute([$n,$h,intdiv(time(),3600)*3600,$op]);$pdo->prepare('DELETE FROM upload_rate_buckets WHERE identity_hash=? AND attempts=0')->execute([$h]);}\n   $pdo->prepare('DELETE FROM user_auth_attempts WHERE identity_hash=?')->execute([hash('sha256','email:login:'.$email)]);\n   $pdo->commit();\n  }catch(Throwable $cleanup){if($pdo->inTransaction())$pdo->rollBack();echo \"CONTRIBUTION_QA_CLEANUP_FAILED\\n\";throw $cleanup;}\n }\n if($key!==null&&$assetId!==null){$s=$pdo->prepare('SELECT COUNT(*) FROM audio_assets WHERE storage_key=?');$s->execute([$key]);if((int)$s->fetchColumn()===0&&is_file($config['storage_path'].'/'.$key))unlink($config['storage_path'].'/'.$key);}\n if(is_string($rawPath)&&is_file($rawPath))unlink($rawPath);\n echo \"CONTRIBUTION_OWNED_QA_RECORDS_AND_MEDIA_CLEANED\\n\";\n}\nif(!$success)exit(1);\necho \"CONTRIBUTION_FULL_HTTP_FLOW_PASS\\n\";\n"
fixture=""
directory=pathlib.Path(tempfile.mkdtemp(prefix='celikom-contribution-flow-',dir='/tmp'))
